     1	import { z } from "zod";
     2	import { orgIdSchema } from "./common";
     3	import { slugSchema } from "./slug";
     4	import { planIdSchema } from "./billing";
     5	
     6	export const organizationSettingsSchema = z.object({
     7	  defaultIssueStatus: z
     8	    .enum(["backlog", "todo", "in_progress", "in_review", "done", "canceled"])
     9	    .default("backlog"),
    10	  allowPublicProjects: z.boolean().default(false),
    11	  requireTwoFactor: z.boolean().default(false),
    12	  digestHourUtc: z.number().int().min(0).max(23).default(7),
    13	  enabledFlagOverrides: z.array(z.string()).default([]),
    14	});
    15	
    16	export const createOrganizationSchema = z.object({
    17	  name: z.string().min(2).max(64),
    18	  slug: slugSchema,
    19	  plan: planIdSchema.default("free"),
    20	});
    21	
    22	export const updateOrganizationSchema = z.object({
    23	  orgId: orgIdSchema,
    24	  name: z.string().min(2).max(64).optional(),
    25	  logoUrl: z.url().nullable().optional(),
    26	  settings: organizationSettingsSchema.partial().optional(),
    27	});
    28	
    29	export const transferOwnershipSchema = z.object({
    30	  orgId: orgIdSchema,
    31	  newOwnerUserId: z.string().min(1),
    32	});
    33	
    34	export const deleteOrganizationSchema = z.object({
    35	  orgId: orgIdSchema,
    36	  confirmSlug: slugSchema,
    37	});
    38	
    39	export type OrganizationSettingsInput = z.infer<
    40	  typeof organizationSettingsSchema
    41	>;
    42	export type CreateOrganizationInput = z.infer<typeof createOrganizationSchema>;
    43	export type UpdateOrganizationInput = z.infer<typeof updateOrganizationSchema>;
    44	export type DeleteOrganizationInput = z.infer<typeof deleteOrganizationSchema>;
    45	export type TransferOwnershipInput = z.infer<typeof transferOwnershipSchema>;
----
     1	"use server";
     2	
     3	/**
     4	 * Updates org profile and settings.
     5	 *
     6	 * Owner D. `settings` is a partial patch — the service merges it over the
     7	 * stored `OrganizationSettings` so a form that only touches `digestHourUtc`
     8	 * cannot silently clear the flag overrides.
     9	 *
    10	 * Must call (do not reimplement): updateOrganizationSchema, can, getActor,
    11	 * toActionResult
    12	 */
    13	
    14	import { ForbiddenActionError } from "@/actions/_lib/action-errors";
    15	import { withAction } from "@/actions/_lib/with-action";
    16	import { CACHE_PROFILES, orgTag, revalidateTagged } from "@/lib/cache";
    17	import { can } from "@/lib/permissions";
    18	import {
    19	  updateOrganizationSchema,
    20	  type UpdateOrganizationInput,
    21	} from "@/schemas/organization";
    22	import { updateOrganization } from "@/server/services/organization-service";
    23	import type { ActionResult } from "@/types/api";
    24	import type { Organization } from "@/types/organization";
    25	
    26	const run = withAction<typeof updateOrganizationSchema, Organization>(
    27	  updateOrganizationSchema,
    28	  async (raw, actor) => {
    29	    const input = raw as UpdateOrganizationInput;
    30	
    31	    if (!can(actor, "org:update", { kind: "organization", orgId: input.orgId })) {
    32	      throw new ForbiddenActionError("org:update");
    33	    }
    34	
    35	    const organization = await updateOrganization(actor, input);
    36	    revalidateTagged([orgTag(input.orgId)], CACHE_PROFILES.minutes);
    37	    return organization;
    38	  },
    39	  { revalidate: ["organization"], cacheProfile: "minutes" },
    40	);
    41	
    42	export async function updateOrganizationAction(
    43	  raw: unknown,
    44	): Promise<ActionResult<Organization>> {
    45	  return run(raw);
    46	}
