     1	/**
     2	 * Organization rows plus slug uniqueness lookups.
     3	 *
     4	 * Must call (do not reimplement): archivePatch, uniqueSlug
     5	 */
     6	import { and, eq, isNull, like } from "drizzle-orm";
     7	import { newId } from "@/lib/id";
     8	import { uniqueSlug } from "@/lib/slug";
     9	import { archivePatch } from "@/lib/soft-delete";
    10	import { getDb, members, organizations } from "@/server/db";
    11	import { toIsoTimestamp } from "@/types/common";
    12	import { toOrganization } from "./_mappers";
    13	import type {
    14	  CreateOrganizationInput,
    15	  UpdateOrganizationInput,
    16	} from "@/schemas/organization";
    17	import type { OrgId, UserId } from "@/types/common";
    18	import type { Organization } from "@/types/organization";
    19	
    20	export async function findOrgById(orgId: OrgId): Promise<Organization | null> {
    21	  const row = getDb()
    22	    .select()
    23	    .from(organizations)
    24	    .where(eq(organizations.id, orgId))
    25	    .get();
    26	  return row ? toOrganization(row) : null;
    27	}
    28	
    29	export async function findOrgBySlug(slug: string): Promise<Organization | null> {
    30	  const row = getDb()
    31	    .select()
    32	    .from(organizations)
    33	    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    34	    .get();
    35	  return row ? toOrganization(row) : null;
    36	}
    37	
    38	/** Every org the user still holds a live membership in. */
    39	export async function listOrgsForUser(
    40	  userId: UserId,
    41	): Promise<readonly Organization[]> {
    42	  const rows = getDb()
    43	    .select({ org: organizations })
    44	    .from(members)
    45	    .innerJoin(organizations, eq(organizations.id, members.orgId))
    46	    .where(
    47	      and(
    48	        eq(members.userId, userId),
    49	        isNull(members.archivedAt),
    50	        isNull(organizations.archivedAt),
    51	      ),
    52	    )
    53	    .all();
    54	
    55	  return rows.map((row) => toOrganization(row.org));
    56	}
    57	
    58	/**
    59	 * Creates the org row. The slug is de-duplicated here rather than in the
    60	 * service so a race on the unique index still resolves to a usable slug.
    61	 */
    62	export async function insertOrg(
    63	  input: CreateOrganizationInput,
    64	  ownerId: UserId,
    65	): Promise<Organization> {
    66	  const taken = await listTakenOrgSlugs(input.slug);
    67	  const slug = uniqueSlug(input.slug, taken);
    68	  const stamp = toIsoTimestamp(new Date());
    69	
    70	  const row = getDb()
    71	    .insert(organizations)
    72	    .values({
    73	      id: newId(),
    74	      name: input.name,
    75	      slug,
    76	      ownerId,
    77	      plan: input.plan,
    78	      logoUrl: null,
    79	      trialEndsAt: null,
    80	      createdAt: stamp,
    81	      updatedAt: stamp,
    82	    })
    83	    .returning()
    84	    .get();
    85	
    86	  return toOrganization(row);
    87	}
    88	
    89	export async function updateOrg(
    90	  orgId: OrgId,
    91	  patch: UpdateOrganizationInput,
    92	): Promise<Organization> {
    93	  const current = await findOrgById(orgId);
    94	  if (!current) throw new Error(`Organization ${orgId} not found`);
    95	
    96	  const settings = { ...current.settings, ...(patch.settings ?? {}) };
    97	
    98	  const row = getDb()
    99	    .update(organizations)
   100	    .set({
   101	      ...(patch.name === undefined ? {} : { name: patch.name }),
   102	      ...(patch.logoUrl === undefined ? {} : { logoUrl: patch.logoUrl }),
   103	      defaultIssueStatus: settings.defaultIssueStatus,
   104	      allowPublicProjects: settings.allowPublicProjects,
   105	      requireTwoFactor: settings.requireTwoFactor,
   106	      digestHourUtc: settings.digestHourUtc,
   107	      enabledFlagOverrides: JSON.stringify(settings.enabledFlagOverrides),
   108	      updatedAt: toIsoTimestamp(new Date()),
   109	    })
   110	    .where(eq(organizations.id, orgId))
   111	    .returning()
   112	    .get();
   113	
   114	  return toOrganization(row);
   115	}
   116	
   117	export async function archiveOrg(orgId: OrgId): Promise<Organization> {
   118	  const row = getDb()
   119	    .update(organizations)
   120	    .set(archivePatch())
   121	    .where(eq(organizations.id, orgId))
   122	    .returning()
   123	    .get();
   124	
