     1	"use client";
     2	
     3	/**
     4	 * Organization profile and settings editor.
     5	 *
     6	 * Owner D. Private to the settings route. `updateOrganizationSchema` accepts a
     7	 * *partial* settings block, so the form only sends the keys it renders — the
     8	 * service merges them over what is stored.
     9	 */
    10	
    11	import { useActionState } from "react";
    12	import { updateOrganizationAction } from "@/actions/organizations/update-organization";
    13	import { fieldErrorsFromZod } from "@/lib/errors";
    14	import { updateOrganizationSchema } from "@/schemas/organization";
    15	import type { ActionResult } from "@/types/api";
    16	import type { Organization } from "@/types/organization";
    17	
    18	export type OrganizationSettingsFormProps = {
    19	  org: Organization;
    20	  disabled: boolean;
    21	};
    22	
    23	type SettingsState = ActionResult<Organization> | null;
    24	
    25	export function OrganizationSettingsForm(props: OrganizationSettingsFormProps) {
    26	  const { org, disabled } = props;
    27	
    28	  const [state, submit, pending] = useActionState<SettingsState, FormData>(
    29	    async (_previous, formData) => {
    30	      const logoUrl = String(formData.get("logoUrl") ?? "").trim();
    31	
    32	      const parsed = updateOrganizationSchema.safeParse({
    33	        orgId: org.id,
    34	        name: String(formData.get("name") ?? ""),
    35	        logoUrl: logoUrl.length === 0 ? null : logoUrl,
    36	        settings: {
    37	          allowPublicProjects: formData.get("allowPublicProjects") === "on",
    38	          requireTwoFactor: formData.get("requireTwoFactor") === "on",
    39	          digestHourUtc: Number(formData.get("digestHourUtc") ?? 7),
    40	        },
    41	      });
    42	
    43	      if (!parsed.success) {
    44	        return {
    45	          ok: false,
    46	          error: {
    47	            code: "validation_failed",
    48	            message: "Check the fields below.",
    49	            fieldErrors: fieldErrorsFromZod(parsed.error),
    50	          },
    51	        };
    52	      }
    53	
    54	      return updateOrganizationAction(parsed.data);
    55	    },
    56	    null,
    57	  );
    58	
    59	  const fieldErrors = state?.ok === false ? (state.error.fieldErrors ?? {}) : {};
    60	
    61	  return (
    62	    <form action={submit} className="space-y-6">
    63	      {state?.ok === true ? (
    64	        <p className="rounded bg-emerald-50 px-3 py-2 text-sm text-emerald-700">
    65	          Settings saved.
    66	        </p>
    67	      ) : null}
    68	      {state?.ok === false && state.error.code === "forbidden" ? (
    69	        <p role="alert" className="rounded bg-rose-50 px-3 py-2 text-sm text-rose-700">
    70	          Your role does not allow changing organization settings.
    71	        </p>
    72	      ) : null}
    73	
    74	      <div className="space-y-1">
    75	        <label htmlFor="name" className="text-sm font-medium">
    76	          Organization name
    77	        </label>
    78	        <input
    79	          id="name"
    80	          name="name"
    81	          defaultValue={org.name}
    82	          disabled={disabled}
    83	          className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm disabled:bg-slate-100"
    84	        />
    85	        {fieldErrors.name !== undefined ? (
    86	          <p className="text-xs text-rose-600">{fieldErrors.name[0]}</p>
    87	        ) : null}
    88	      </div>
    89	
    90	      <div className="space-y-1">
    91	        <label htmlFor="logoUrl" className="text-sm font-medium">
    92	          Logo URL
    93	        </label>
    94	        <input
    95	          id="logoUrl"
    96	          name="logoUrl"
    97	          type="url"
    98	          defaultValue={org.logoUrl ?? ""}
    99	          disabled={disabled}
   100	          className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm disabled:bg-slate-100"
   101	        />
   102	      </div>
   103	
   104	      <div className="space-y-1">
   105	        <label htmlFor="digestHourUtc" className="text-sm font-medium">
   106	          Digest hour (UTC)
   107	        </label>
   108	        <input
   109	          id="digestHourUtc"
   110	          name="digestHourUtc"
   111	          type="number"
   112	          min={0}
   113	          max={23}
   114	          defaultValue={org.settings.digestHourUtc}
   115	          disabled={disabled}
   116	          className="w-24 rounded-md border border-slate-300 px-3 py-2 text-sm disabled:bg-slate-100"
   117	        />
   118	        <p className="text-xs text-slate-500">
   119	          The daily digest job runs once an hour and picks up organizations whose
   120	          hour has come round.
   121	        </p>
   122	      </div>
   123	
   124	      <label className="flex items-center gap-2 text-sm">
   125	        <input
   126	          type="checkbox"
   127	          name="allowPublicProjects"
   128	          defaultChecked={org.settings.allowPublicProjects}
   129	          disabled={disabled}
   130	        />
   131	        Allow projects to be made public
   132	      </label>
   133	
   134	      <label className="flex items-center gap-2 text-sm">
   135	        <input
   136	          type="checkbox"
   137	          name="requireTwoFactor"
   138	          defaultChecked={org.settings.requireTwoFactor}
   139	          disabled={disabled}
   140	        />
   141	        Require two-factor authentication
   142	      </label>
   143	
   144	      <button
   145	        type="submit"
   146	        disabled={disabled || pending}
   147	        className="rounded-md bg-indigo-600 px-4 py-2 text-sm font-medium text-white disabled:opacity-60"
   148	      >
   149	        {pending ? "Saving…" : "Save settings"}
   150	      </button>
   151	    </form>
   152	  );
   153	}
----
     1	/**
     2	 * General organization settings.
     3	 *
     4	 * Owner D. Name, logo and the `OrganizationSettings` block. Read access is
     5	 * `org:read` (everyone), write access is `org:update` (admin and above), so the
     6	 * page renders for a viewer with the form disabled rather than 404ing.
     7	 *
     8	 * Must call (do not reimplement): can
     9	 */
    10	
    11	import type { Metadata } from "next";
    12	import { can } from "@/lib/permissions";
    13	import { loadTenantContext } from "../_lib/tenant-context";
    14	import { OrganizationSettingsForm } from "./organization-settings-form";
    15	
    16	type PageParams = { orgSlug: string };
    17	
    18	export const dynamic = "force-dynamic";
    19	
    20	export const metadata: Metadata = {
    21	  title: "General settings",
    22	};
    23	
    24	export default async function Page(props: {
    25	  params: Promise<PageParams>;
    26	  searchParams: Promise<Record<string, string | string[] | undefined>>;
    27	}) {
    28	  // Next.js 16: params and searchParams are Promises and MUST be awaited.
    29	  const { orgSlug } = await props.params;
    30	  await props.searchParams;
    31	
    32	  const { org, actor } = await loadTenantContext(orgSlug);
    33	
    34	  const mayEdit = can(actor, "org:update", {
    35	    kind: "organization",
    36	    orgId: org.id,
    37	  });
    38	
    39	  return (
    40	    <div className="max-w-xl space-y-8">
    41	      <header>
    42	        <h1 className="text-xl font-semibold tracking-tight">General</h1>
    43	        <p className="mt-1 text-sm text-slate-600">
    44	          The name and defaults everybody in {org.name} sees.
    45	        </p>
    46	      </header>
    47	
    48	      <OrganizationSettingsForm org={org} disabled={!mayEdit} />
    49	
    50	      {!mayEdit ? (
    51	        <p className="text-xs text-slate-500">
    52	          Only admins and owners can change these settings.
    53	        </p>
    54	      ) : null}
    55	    </div>
    56	  );
    57	}

