     1	"use server";
     2	
     3	/**
     4	 * Toggles an org-level feature flag override.
     5	 *
     6	 * Owner D. An override can only *turn on* a flag whose definition is
     7	 * `overridable`; `isEnabled()` is consulted first so that toggling a flag which
     8	 * is already on for structural reasons (plan or rollout percentage) is a no-op
     9	 * rather than a confusing write.
    10	 *
    11	 * Must call (do not reimplement): toggleFeatureFlagSchema, can, isEnabled,
    12	 * getActor, toActionResult
    13	 */
    14	
    15	import { ForbiddenActionError } from "@/actions/_lib/action-errors";
    16	import { withAction } from "@/actions/_lib/with-action";
    17	import { CACHE_PROFILES, orgTag, revalidateTagged } from "@/lib/cache";
    18	import { isEnabled } from "@/lib/feature-flags";
    19	import { can } from "@/lib/permissions";
    20	import {
    21	  toggleFeatureFlagSchema,
    22	  type ToggleFeatureFlagInput,
    23	} from "@/schemas/feature-flag";
    24	import {
    25	  buildFlagContext,
    26	  toggleFlag,
    27	} from "@/server/services/feature-flag-service";
    28	import { getOrganizationSummary } from "@/server/services/organization-service";
    29	import type { ActionResult } from "@/types/api";
    30	import type { Organization } from "@/types/organization";
    31	
    32	const run = withAction<typeof toggleFeatureFlagSchema, Organization>(
    33	  toggleFeatureFlagSchema,
    34	  async (raw, actor) => {
    35	    const input = raw as ToggleFeatureFlagInput;
    36	
    37	    if (!can(actor, "org:manage_flags", { kind: "organization", orgId: input.orgId })) {
    38	      throw new ForbiddenActionError("org:manage_flags");
    39	    }
    40	
    41	    const { organization } = await getOrganizationSummary(actor, input.orgId);
    42	    const context = buildFlagContext(actor, organization);
    43	    if (isEnabled(input.flag, context) === input.enabled) {
    44	      return organization;
    45	    }
    46	
    47	    const updated = await toggleFlag(actor, input);
    48	    revalidateTagged([orgTag(input.orgId)], CACHE_PROFILES.minutes);
    49	    return updated;
    50	  },
    51	  { revalidate: ["flags"], cacheProfile: "minutes" },
    52	);
    53	
    54	export async function toggleFeatureFlagAction(
    55	  raw: unknown,
    56	): Promise<ActionResult<Organization>> {
    57	  return run(raw);
    58	}
