     1	/**
     2	 * Server-side flag context construction and the org-level override toggle.
     3	 *
     4	 * Must call (do not reimplement): assertCan, isEnabled, snapshotFlags, emit
     5	 */
     6	import { emit } from "@/lib/event-bus";
     7	import { isEnabled, snapshotFlags } from "@/lib/feature-flags";
     8	import { assertCan } from "@/lib/permissions";
     9	import { getFlagDefinition } from "@/config/feature-flags";
    10	import * as orgRepo from "@/server/repositories/organization-repository";
    11	import { actorEnvelope, orgResource, requireFound } from "./_support";
    12	import type { ToggleFeatureFlagInput } from "@/schemas/feature-flag";
    13	import type { FeatureFlagSnapshot, FlagContext } from "@/types/feature-flag";
    14	import type { Actor } from "@/types/member";
    15	import type { Organization } from "@/types/organization";
    16	
    17	/**
    18	 * Builds the evaluation context every `isEnabled()` call needs. Both halves
    19	 * are nullable so marketing pages — no session, no org — can still ask about
    20	 * a flag and get the free-plan answer.
    21	 */
    22	export function buildFlagContext(
    23	  actor: Actor | null,
    24	  org: Organization | null,
    25	): FlagContext {
    26	  return {
    27	    orgId: org?.id ?? actor?.orgId ?? null,
    28	    userId: actor?.userId ?? null,
    29	    plan: org?.plan ?? "free",
    30	    role: actor?.role ?? null,
    31	    overrides: org?.settings.enabledFlagOverrides,
    32	  };
    33	}
    34	
    35	/**
    36	 * The serialisable snapshot the dashboard layout hands to the client provider,
    37	 * so `useFeatureFlag()` answers without a round trip and cannot disagree with
    38	 * the server.
    39	 */
    40	export function getSnapshot(
    41	  actor: Actor,
    42	  org: Organization,
    43	): FeatureFlagSnapshot {
    44	  return snapshotFlags(buildFlagContext(actor, org));
    45	}
    46	
    47	/**
    48	 * Adds or removes an org-level override. Only flags declared `overridable`
    49	 * accept one — a flag gated purely on plan cannot be switched on by an admin,
    50	 * which is what keeps the plan boundary meaningful.
    51	 */
    52	export async function toggleFlag(
    53	  actor: Actor,
    54	  input: ToggleFeatureFlagInput,
    55	): Promise<Organization> {
    56	  assertCan(actor, "org:manage_flags", orgResource(input.orgId));
    57	
    58	  const org = requireFound(
    59	    await orgRepo.findOrgById(input.orgId),
