     1	/**
     2	 * Loads the three things every page under `[orgSlug]` needs: the organization,
     3	 * the caller's `Actor` inside it, and the feature-flag snapshot.
     4	 *
     5	 * Owner D. Private to the tenant subtree. It exists so that no page has to
     6	 * remember the order of operations — resolve the org, resolve the actor, assert
     7	 * they agree, only then evaluate flags. Getting that order wrong is how a page
     8	 * ends up evaluating flags against somebody else's plan.
     9	 */
    10	
    11	import { notFound } from "next/navigation";
    12	import { getActor } from "@/lib/actor";
    13	import { snapshotFlags } from "@/lib/feature-flags";
    14	import { assertOrgScope } from "@/lib/tenant";
    15	import { buildFlagContext } from "@/server/services/feature-flag-service";
    16	import { resolveOrgBySlug } from "@/server/services/organization-service";
    17	import type { FeatureFlagSnapshot } from "@/types/feature-flag";
    18	import type { Actor } from "@/types/member";
    19	import type { Organization } from "@/types/organization";
    20	
    21	export type TenantContext = {
    22	  readonly org: Organization;
    23	  readonly actor: Actor;
    24	  readonly flags: FeatureFlagSnapshot;
    25	};
    26	
    27	/**
    28	 * A missing organization and an organization the caller cannot reach are the
    29	 * same 404 on purpose: distinguishing them would leak which slugs exist.
    30	 */
    31	export async function loadTenantContext(orgSlug: string): Promise<TenantContext> {
    32	  const org = await resolveOrgBySlug(orgSlug);
    33	  if (org === null) {
    34	    notFound();
    35	  }
    36	
    37	  const actor = await getActor(orgSlug);
    38	  assertOrgScope(actor, org.id);
    39	
    40	  const flags = snapshotFlags(buildFlagContext(actor, org));
    41	  return { org, actor, flags };
    42	}
