import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { updateOrganizationSchema } from "@/schemas/organization";
import { updateOrganization } from "@/server/services/organization-service";
import * as orgRepo from "@/server/repositories/organization-repository";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("organization settings patch", () => {
  it("keeps unsubmitted settings when only allowPublicProjects is saved", async () => {
    const tenant = await createTenant("alpha", "growth");
    await orgRepo.updateOrg(tenant.org.id, {
      orgId: tenant.org.id,
      settings: {
        digestHourUtc: 18,
        requireTwoFactor: true,
        defaultIssueStatus: "todo",
        enabledFlagOverrides: ["digest_email", "activity_feed"],
      },
    });

    const updated = await updateOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      settings: { allowPublicProjects: true },
    });

    expect(updated.settings).toEqual({
      defaultIssueStatus: "todo",
      allowPublicProjects: true,
      requireTwoFactor: true,
      digestHourUtc: 18,
      enabledFlagOverrides: ["digest_email", "activity_feed"],
    });
  });

  it("renaming changes no settings", async () => {
    const tenant = await createTenant("bravo", "growth");
    await orgRepo.updateOrg(tenant.org.id, {
      orgId: tenant.org.id,
      settings: { digestHourUtc: 9, enabledFlagOverrides: ["webhooks"] },
    });
    const before = (await orgRepo.findOrgById(tenant.org.id))!.settings;

    const renamed = await updateOrganization(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Bravo Renamed",
    });

    expect(renamed.name).toBe("Bravo Renamed");
    expect(renamed.settings).toEqual(before);
  });

  it("writes falsy submitted values: 0, false and an empty list", async () => {
    const tenant = await createTenant("charlie", "growth");
    await orgRepo.updateOrg(tenant.org.id, {
      orgId: tenant.org.id,
      settings: {
        digestHourUtc: 12,
        requireTwoFactor: true,
        allowPublicProjects: true,
        enabledFlagOverrides: ["digest_email"],
      },
    });

    const updated = await updateOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      settings: {
        digestHourUtc: 0,
        requireTwoFactor: false,
        enabledFlagOverrides: [],
      },
    });

    expect(updated.settings.digestHourUtc).toBe(0);
    expect(updated.settings.requireTwoFactor).toBe(false);
    expect(updated.settings.enabledFlagOverrides).toEqual([]);
    expect(updated.settings.allowPublicProjects).toBe(true);
  });

  it("does not touch another workspace", async () => {
    const one = await createTenant("delta", "growth");
    const two = await createTenant("echo", "growth");
    await orgRepo.updateOrg(two.org.id, {
      orgId: two.org.id,
      settings: { digestHourUtc: 3, requireTwoFactor: true },
    });

    await updateOrganization(one.actors.owner, {
      orgId: one.org.id,
      settings: { digestHourUtc: 20, requireTwoFactor: false },
    });

    const other = (await orgRepo.findOrgById(two.org.id))!;
    expect(other.settings.digestHourUtc).toBe(3);
    expect(other.settings.requireTwoFactor).toBe(true);
  });

  it("the action schema does not add defaults to a partial settings block", () => {
    const parsed = updateOrganizationSchema.parse({
      orgId: "org_x",
      settings: { allowPublicProjects: true },
    });
    expect(parsed.settings).toEqual({ allowPublicProjects: true });
  });
});

